class Solution {
  public int[] dispatchOrderProofStrip(int[][] links, int k) {
    int[][] a=links; List<Integer> out=new ArrayList<>();
    {int n=a.length;int[]degree=new int[n];for(int[]row:a)for(int v=0;v<n;v++)degree[v]+=row[v];Deque<Integer>queue=new ArrayDeque<>();for(int v=0;v<n;v++)if(degree[v]==0)queue.add(v);while(!queue.isEmpty()){int u=queue.remove();out.add(u);for(int v=0;v<n;v++)if(a[u][v]!=0&&--degree[v]==0)queue.add(v);}if(out.size()!=n)out.clear();}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
